use std::fs
use std::collections::HashMap

struct Row {
    name: string,
    count: int,
    total: int,
    top: string,
}

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut bad = 0
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut totals: HashMap<string, int> = HashMap::new()
    let mut acts: HashMap<string, int> = HashMap::new()
    let mut users: Vec<string> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split(" ").collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        let u = parts[0]
        let secs: int = parts[2].parse::<int>().unwrap_or(0)
        if !counts.contains_key(u) {
            users.push(u)
            counts.insert(u, 0)
            totals.insert(u, 0)
        }
        counts.insert(u, counts.get(u).unwrap_or(0) + 1)
        totals.insert(u, totals.get(u).unwrap_or(0) + secs)
        let key = "${u} ${parts[1]}"
        acts.insert(key, acts.get(key).unwrap_or(0) + 1)
    }
    let mut rows: Vec<Row> = []
    for u in users {
        let mut best = ""
        let mut bc = 0
        for k in acts.keys() {
            let pre = "${u} "
            if k.starts_with(pre) {
                let a = k[pre.len()..k.len()]
                let c = acts.get(k).unwrap_or(0)
                if c > bc || (c == bc && a < best) {
                    bc = c
                    best = a
                }
            }
        }
        rows.push(Row { name: u, count: counts.get(u).unwrap_or(0), total: totals.get(u).unwrap_or(0), top: best })
    }
    rows.sort_by(|a, b| {
        if a.total != b.total {
            b.total.cmp(a.total)
        } else {
            a.name.cmp(b.name)
        }
    })
    for r in rows {
        println("${r.name} ${r.count} ${r.total} ${r.top}")
    }
    println("malformed: ${bad}")
}

